SAS (Statistical Analysis System) is a software suite for advanced analytics, business intelligence, data management, and predictive analytics. Widely used in pharmaceuticals, finance, and government.

A SAS program consists of:
1. **DATA steps** — read, create, modify datasets
2. **PROC steps** — analyze and process datasets
3. **Global statements** — apply throughout the program

```sas
/* Comments: slash-asterisk style */
* This is also a comment ;

/* Define a library (folder) */
libname mylib '/path/to/data';

/* Global options */
options nodate nonumber ls=120;
title 'My SAS Analysis';

/* Basic DATA step */
data work.students;
    input name $ age score gpa;
    datalines;
Alice 20 85 3.5
Bob 22 92 3.8
Carol 21 78 3.2
;
run;

/* Basic PROC step */
proc print data=work.students;
run;

/* Run batch mode */
/* sas hello.sas */
```

```sas
data work.demo;
    /* Numeric variable */
    x = 42;
    y = 3.14;

    /* Character variable ($ suffix) */
    name = 'Alice';

    /* Date/time */
    today = today();
    now = datetime();
    put today date9.;      /* 25MAY2026 */

    /* Arithmetic */
    z  = (x + y) ** 2;    /* ** is power */
    z2 = sqrt(x);
    z3 = abs(-10);
    z4 = log(x);          /* natural log */
    z5 = log10(x);
    r  = mod(10, 3);       /* remainder: 1 */
    f  = floor(3.7);       /* 3 */
    c  = ceil(3.2);        /* 4 */
    rn = round(3.567, 0.01); /* 3.57 */
    u  = ranuni(0);        /* uniform 0-1 */
    n2 = rannor(0);        /* standard normal */

    /* String functions */
    s = 'Hello, World!';
    len  = length(s);              /* 13 */
    up   = upcase(s);              /* HELLO, WORLD! */
    sub  = substr(s, 1, 5);        /* Hello */
    pos  = index(s, 'World');      /* 8 */
    trm  = strip(s);
    cat2 = catx(' ', 'Hello', 'World'); /* Hello World */

    /* Numeric to string */
    ns = strip(put(42, best12.));  /* '42' */

    /* String to numeric */
    num = input('3.14', best12.);  /* 3.14 */
run;

/* Declare variable lengths */
data work.lengths;
    length name $ 20  city $ 30  score 8;
    name = 'Alice'; city = 'New York'; score = 95.5;
run;
```

```sas
data work.classified;
    set work.students;

    /* if-then-else */
    if score >= 90 then grade = 'A';
    else if score >= 80 then grade = 'B';
    else if score >= 70 then grade = 'C';
    else grade = 'F';

    /* select (case) */
    select (grade);
        when ('A') honor = 'Dean''s List';
        when ('B') honor = 'Good Standing';
        otherwise honor = 'Probation';
    end;

    /* Conditional output to separate datasets */
    if score >= 85 then output work.honors;
    else output work.regular;
run;

data work.loops;
    /* DO loop */
    total = 0;
    do i = 1 to 10;
        total = total + i;
    end;
    put total=;    /* total=55 */

    /* DO WHILE */
    n = 1;
    do while (n < 100);
        n = n * 2;
    end;
    put n=;        /* n=128 */

    /* DO UNTIL */
    m = 0;
    do until (m >= 50);
        m = m + 7;
    end;
run;

/* Arrays — process multiple variables at once */
data work.arrays;
    set work.scores_wide;
    array scores{5} score1-score5;

    total = 0;
    do i = 1 to 5;
        total = total + scores{i};
    end;
    avg = total / 5;
run;
```

```sas
/* PROC PRINT — display data */
proc print data=work.students;
    title 'Student Data';
    var name age score gpa;
run;

/* PROC MEANS — descriptive statistics */
proc means data=work.students n mean std min max;
    var score gpa age;
run;

/* PROC FREQ — frequency tables and chi-square */
proc freq data=work.students;
    tables grade / nocum nopercent;
    tables grade * honor / chisq;
run;

/* PROC SORT — sort dataset */
proc sort data=work.students out=work.sorted;
    by descending score;
run;

/* PROC UNIVARIATE — detailed distribution */
proc univariate data=work.students normal;
    var score;
    histogram / normal;
    qqplot / normal;
run;

/* PROC CORR — correlation matrix */
proc corr data=work.students;
    var score gpa age;
run;

/* PROC REG — linear regression */
proc reg data=work.students;
    model score = age gpa;
    output out=work.predicted predicted=pred residual=resid;
run;

/* PROC GLM — ANOVA and general linear models */
proc glm data=work.students;
    class grade;
    model score = grade;
    means grade / tukey;
    lsmeans grade / pdiff;
run;

/* PROC TTEST — t-test */
proc ttest data=work.students;
    class gender;
    var score;
run;
```

```sas
/* MERGE — sort both datasets first! */
proc sort data=work.students; by name; run;
proc sort data=work.scores;   by name; run;

data work.merged;
    merge work.students (in=a)
          work.scores   (in=b);
    by name;
    if a and b;     /* inner join */
    /* if a;        left join */
    /* (no filter)  full outer join */
run;

/* RETAIN — carry variable across iterations */
data work.cumsum;
    set work.students;
    retain running_total 0;
    running_total = running_total + score;
run;

/* FIRST. and LAST. — BY-group processing */
proc sort data=work.students; by grade; run;

data work.bygrade;
    set work.students;
    by grade;
    if first.grade then count = 0;
    retain count;
    count + 1;
    if last.grade then output;   /* output one row per grade */
run;

/* LAG — access previous observation's value */
data work.lagged;
    set work.timeseries;
    prev_value  = lag(value);
    change      = value - lag(value);
    pct_change  = (value / lag(value) - 1) * 100;
run;

/* WHERE — filter rows */
data work.filtered;
    set work.students;
    where score >= 80 and gpa > 3.0;
run;

/* RENAME and DROP/KEEP */
data work.clean;
    set work.students (rename=(score=test_score));
    drop age;
run;
```

```sas
/* Macro variables */
%let year = 2026;
%let cutoff = 80;
%put The year is &year;       /* prints to log */

/* Use in PROC SQL */
proc sql;
    select * from work.students
    where score >= &cutoff;
quit;

/* Macro definition */
%macro analyze(dataset=, var=, alpha=0.05);
    proc means data=&dataset;
        var &var;
        title "Analysis of &var in &dataset";
    run;
    proc univariate data=&dataset;
        var &var;
        histogram / normal(alpha=&alpha);
    run;
%mend analyze;

/* Invoke macro */
%analyze(dataset=work.students, var=score)
%analyze(dataset=work.students, var=gpa, alpha=0.01)

/* Conditional macro */
%macro check(n);
    %if &n > 100 %then %do;
        %put Large N: &n;
    %end;
    %else %do;
        %put Small N: &n;
    %end;
%mend;
%check(50)
%check(200)

/* Macro DO loop */
%macro multireg;
    %do i = 1 %to 5;
        proc reg data=work.data&i;
            model y = x1 x2;
        run;
    %end;
%mend;
%multireg

/* Pass data value to macro variable */
data _null_;
    n = 42;
    call symput('myval', n);
run;
%put myval = &myval;   /* myval = 42 */
```

```sas
/* Basic SELECT */
proc sql;
    select name, age, score
    from work.students
    where score >= 80
    order by score desc;
quit;

/* Aggregation with GROUP BY and HAVING */
proc sql;
    select grade,
           count(*) as n,
           mean(score) as avg_score,
           std(score) as std_score,
           min(score) as min_score,
           max(score) as max_score
    from work.students
    group by grade
    having count(*) >= 2
    order by grade;
quit;

/* Joins */
proc sql;
    /* Inner join */
    select a.name, a.score, b.department
    from work.students a
    inner join work.departments b
    on a.dept_id = b.dept_id;

    /* Left join */
    select a.*, b.bonus
    from work.employees a
    left join work.bonuses b
    on a.id = b.emp_id;
quit;

/* CREATE TABLE */
proc sql;
    create table work.summary as
    select grade,
           count(*) as n,
           mean(score) as avg_score format=8.2
    from work.students
    group by grade;
quit;

/* Store result in macro variable */
proc sql noprint;
    select mean(score)
    into :avg_score
    from work.students;
quit;
%put Average score: &avg_score;

/* Subquery */
proc sql;
    select name, score
    from work.students
    where score > (select mean(score) from work.students);
quit;
```

```sas
/* ODS — generate output in different formats */

/* HTML output */
ods html file='/output/report.html' style=HTMLBlue;
proc means data=work.students;
    var score gpa;
run;
ods html close;

/* PDF output */
ods pdf file='/output/report.pdf';
title 'Student Analysis Report';
proc print data=work.students; run;
proc freq data=work.students; tables grade; run;
ods pdf close;

/* Excel output */
ods excel file='/output/results.xlsx';
proc print data=work.students; run;
ods excel close;

/* PROC FORMAT — custom display formats */
proc format;
    value gradefmt
        90 - 100 = 'A'
        80 -  89 = 'B'
        70 -  79 = 'C'
              low - 69 = 'F';

    value $genderfmt
        'M' = 'Male'
        'F' = 'Female';
run;

data work.formatted;
    set work.students;
    format score gradefmt. gender $genderfmt.;
run;

/* PROC REPORT — custom tabular reports */
proc report data=work.students nowindows;
    column name age score grade;
    define name  / display 'Student Name';
    define score / display 'Score' format=5.1;
    define grade / display 'Grade';
    compute grade;
        if score >= 90 then call define(_col_, 'style',
            'style=[background=green]');
    endcomp;
run;

/* Debugging options */
options mprint mlogic symbolgen;  /* macro debugging */
options obs=10;                    /* limit rows for testing */
proc contents data=work.students; run;
```
